CREATE TABLE "EpgChannelMapping" ("id" TEXT PRIMARY KEY,"sourceId" TEXT NOT NULL,"externalChannelId" TEXT NOT NULL,"externalName" TEXT,"channelId" TEXT,"confidence" DOUBLE PRECISION,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "EpgImportRun" ("id" TEXT PRIMARY KEY,"sourceId" TEXT NOT NULL,"status" TEXT NOT NULL,"channelsSeen" INTEGER NOT NULL DEFAULT 0,"programsImported" INTEGER NOT NULL DEFAULT 0,"invalidDates" INTEGER NOT NULL DEFAULT 0,"errorCode" TEXT,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"finishedAt" TIMESTAMP(3));
CREATE TABLE "EpgProgram" ("id" TEXT PRIMARY KEY,"mappingId" TEXT NOT NULL,"channelId" TEXT,"externalId" TEXT NOT NULL,"title" JSONB NOT NULL,"description" JSONB,"category" TEXT,"startAt" TIMESTAMP(3) NOT NULL,"endAt" TIMESTAMP(3) NOT NULL,"sourceUpdatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ProgramReminder" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"programId" TEXT NOT NULL,"notifyAt" TIMESTAMP(3) NOT NULL,"sentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ChannelAvailability" ("id" TEXT PRIMARY KEY,"channelId" TEXT NOT NULL,"sourceId" TEXT,"available" BOOLEAN NOT NULL,"latencyMs" INTEGER,"checkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "EpgChannelMapping_sourceId_externalChannelId_key" ON "EpgChannelMapping"("sourceId","externalChannelId"); CREATE INDEX "EpgChannelMapping_sourceId_channelId_idx" ON "EpgChannelMapping"("sourceId","channelId");
CREATE INDEX "EpgImportRun_sourceId_startedAt_idx" ON "EpgImportRun"("sourceId","startedAt"); CREATE UNIQUE INDEX "EpgProgram_mappingId_externalId_key" ON "EpgProgram"("mappingId","externalId"); CREATE INDEX "EpgProgram_channelId_startAt_endAt_idx" ON "EpgProgram"("channelId","startAt","endAt");
CREATE UNIQUE INDEX "ProgramReminder_userId_programId_key" ON "ProgramReminder"("userId","programId"); CREATE INDEX "ProgramReminder_notifyAt_sentAt_idx" ON "ProgramReminder"("notifyAt","sentAt"); CREATE INDEX "ChannelAvailability_channelId_checkedAt_idx" ON "ChannelAvailability"("channelId","checkedAt"); CREATE INDEX "ChannelAvailability_sourceId_checkedAt_idx" ON "ChannelAvailability"("sourceId","checkedAt");
ALTER TABLE "EpgChannelMapping" ADD CONSTRAINT "EpgChannelMapping_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "SourceAccount"("id") ON DELETE CASCADE; ALTER TABLE "EpgChannelMapping" ADD CONSTRAINT "EpgChannelMapping_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "Channel"("id") ON DELETE SET NULL;
ALTER TABLE "EpgImportRun" ADD CONSTRAINT "EpgImportRun_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "SourceAccount"("id") ON DELETE CASCADE;
ALTER TABLE "EpgProgram" ADD CONSTRAINT "EpgProgram_mappingId_fkey" FOREIGN KEY ("mappingId") REFERENCES "EpgChannelMapping"("id") ON DELETE CASCADE; ALTER TABLE "EpgProgram" ADD CONSTRAINT "EpgProgram_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE;
ALTER TABLE "ProgramReminder" ADD CONSTRAINT "ProgramReminder_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "ProgramReminder" ADD CONSTRAINT "ProgramReminder_programId_fkey" FOREIGN KEY ("programId") REFERENCES "EpgProgram"("id") ON DELETE CASCADE;
ALTER TABLE "ChannelAvailability" ADD CONSTRAINT "ChannelAvailability_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE;
